let handlingUnauthorized = false

function handleUnauthorized(path: string, headers: Record<string, string>): void {
  const authorization = Object.entries(headers).find(([key]) => key.toLowerCase() === 'authorization')?.[1].trim()
  const normalizedPath = `/${path.split(/[?#]/, 1)[0].replace(/^\\/+|\\/+$/g, '')}`
  if (!authorization || normalizedPath === '/v2.0/security/auth/login') return

  clearToken()
  clearLoginUser()
  if (handlingUnauthorized) return
  handlingUnauthorized = true

  const pages = typeof getCurrentPages === 'function' ? getCurrentPages() : []
  const currentRoute = pages[pages.length - 1]?.route?.replace(/^\\/+|\\/+$/g, '')
  if (!pages.length || currentRoute === 'pages/login/index') {
    handlingUnauthorized = false
    return
  }

  try {
    uni.reLaunch({
      url: '/pages/login/index',
      complete: () => { handlingUnauthorized = false },
    })
  } catch {
    handlingUnauthorized = false
  }
}

