  const request = createRequest(async () => ({ statusCode: 200, data: { id: 'record-1' } }), 'https://api.example.test')
  expect(await request<{ id: string }>('/records/record-1')).toEqual({ id: 'record-1' })
  const failed = createRequest(async () => ({ statusCode: 503, data: {} }), 'https://api.example.test')
  await expect(failed('/records')).rejects.toThrow('503')
