function setupUnauthorizedContext(route = 'pages/home/index') {
  const bag = withUniStorage()
  const reLaunch = vi.fn((options: { complete: () => void }) => undefined)
  ;(globalThis as unknown as { uni: unknown }).uni = { ...globalThis.uni, reLaunch }
  ;(globalThis as unknown as { getCurrentPages: () => Array<{ route: string }> }).getCurrentPages = () => [{ route }]
  setToken('expired-token')
  setLoginUser({ userId: '1', userName: 'tester' })
  return { bag, reLaunch }
}

function unauthorizedRequest(path = '/records') {
  return createRequest(async () => ({ statusCode: 401, data: { msg: 'Unauthorized' } }), {
    baseUrl: 'https://api.example.test', projectId: 'test', getToken: () => 'expired-token',
  })(path)
}

test('带 token 的请求收到401时清理登录态、返回登录页并保留原错误', async () => {
  const { reLaunch } = setupUnauthorizedContext()
  await expect(unauthorizedRequest()).rejects.toThrow('Unauthorized')
  expect(getToken()).toBeUndefined()
  expect(getLoginUser()).toBeUndefined()
  expect(reLaunch).toHaveBeenCalledTimes(1)
  expect(reLaunch.mock.calls[0][0]).toMatchObject({ url: '/pages/login/index' })
  reLaunch.mock.calls[0][0].complete()
})

test('登录接口401不清理状态或重复跳转', async () => {
  const { reLaunch } = setupUnauthorizedContext()
  const loginRequest = createRequest(async () => ({ statusCode: 401, data: {} }), {
    baseUrl: 'https://api.example.test', projectId: 'test', getToken: () => 'expired-token',
  })
  await expect(loginRequest('/v2.0/security/auth/login')).rejects.toThrow('401')
  expect(getToken()).toBe('expired-token')
  expect(getLoginUser()).toBeDefined()
  expect(reLaunch).not.toHaveBeenCalled()
})

test('并发401只跳转一次，已在登录页只清理且导航锁可再次使用', async () => {
  const first = setupUnauthorizedContext()
  await Promise.all([
    expect(unauthorizedRequest('/records/a')).rejects.toThrow('401'),
    expect(unauthorizedRequest('/records/b')).rejects.toThrow('401'),
  ])
  expect(first.reLaunch).toHaveBeenCalledTimes(1)
  first.reLaunch.mock.calls[0][0].complete()

  const second = setupUnauthorizedContext('pages/login/index')
  await expect(unauthorizedRequest()).rejects.toThrow('401')
  expect(getToken()).toBeUndefined()
  expect(getLoginUser()).toBeUndefined()
  expect(second.reLaunch).not.toHaveBeenCalled()
  const third = setupUnauthorizedContext()
  await expect(unauthorizedRequest()).rejects.toThrow('401')
  expect(third.reLaunch).toHaveBeenCalledTimes(1)
  third.reLaunch.mock.calls[0][0].complete()
})
